def moore(n,m,trans,acc):
    block=[1 if x else 0 for x in acc]
    if len(set(block))==1:return [0]*n
    while True:
        mp={};new=[0]*n
        for s in range(n):
            key=(block[s],)+tuple(block[trans[s][a]] for a in range(m))
            if key not in mp:mp[key]=len(mp)
            new[s]=mp[key]
        if len(mp)==len(set(block)) and all((new[i]==new[j])==(block[i]==block[j]) for i in range(n) for j in range(n)):
            # Actually compare partition equality rather than IDs
            pass
        # normalize and compare equivalence relation / number
        # check stable: every old block exactly one new block
        oldfirst={}
        stable=True
        for s in range(n):
            b=block[s]
            if b in oldfirst and oldfirst[b]!=new[s]: stable=False;break
            oldfirst[b]=new[s]
        block=new
        if stable:return block

def tablefill(n,m,trans,acc):
    # distinguishable pair algorithm O(n^2), return equivalence labels
    dist=[[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1,n):
            if acc[i]!=acc[j]:dist[i][j]=dist[j][i]=True
    changed=True
    while changed:
        changed=False
        for i in range(n):
            for j in range(i+1,n):
                if dist[i][j]:continue
                for a in range(m):
                    x,y=trans[i][a],trans[j][a]
                    if x!=y and dist[x][y]:
                        dist[i][j]=dist[j][i]=True;changed=True;break
    # grouping
    groups=[]
    for i in range(n):
        for g in groups:
            if not dist[i][g[0]]:
                g.append(i);break
        else:groups.append([i])
    b=[0]*n
    for k,g in enumerate(groups):
        for s in g:b[s]=k
    return b

