"""JSON batch entry point for the eMicro CPU control-plane contract."""
from __future__ import annotations

import json
import math
import re
import sys

from ebpf.helper import Agent
from syntax import PolicyError, parse_policy

U32 = 4294967295
MIB = 1024 * 1024
LIMITS = {
    "images": 16, "cells": 262144, "units": 1024, "contexts": 32768,
    "connections": 4096, "packets": 32768, "files": 8192,
}
NAME = re.compile(r"[A-Za-z][A-Za-z0-9]{0,23}\Z")
SCHEMA = {
    "stage": {"epoch": "positive", "policy": "text"},
    "commit": {"epoch": "positive"},
    "retire": {"epoch": "positive"},
    "spawn": {"unit": "unit", "service": "name"},
    "clone": {"parent": "unit", "child": "unit"},
    "exit": {"unit": "unit"},
    "begin": {"unit": "unit", "rid": "positive"},
    "finish": {"unit": "unit", "rid": "positive"},
    "open": {"connection": "pair"},
    "close": {"connection": "pair"},
    "send": {"unit": "unit", "rid": "positive", "connection": "pair",
             "stream": "positive", "destination": "name"},
    "recv": {"unit": "unit", "rid": "positive", "connection": "pair",
             "stream": "positive", "wire": "wire"},
    "store": {"unit": "unit", "rid": "positive", "file": "pair"},
    "load": {"unit": "unit", "rid": "positive", "file": "pair"},
    "unlink": {"file": "pair"},
    "inspect": {},
}
JOB_KEYS = {"services", "limits", "events"}
EVENT_COUNT_MAX = 200000
STAGES_MAX = 16
POLICY_BYTES_MAX = 8 * MIB
ATOM_TOTAL_MAX = 32768
PATH_TOTAL_MAX = 65536
RAW_MAX = 24 * MIB

# Make the integer-token rule independent of the process's Python startup
# environment.  CPython counts decimal digits excluding the leading sign.
try:
    sys.set_int_max_str_digits(4300)
except (AttributeError, ValueError):
    pass


class Invalid(ValueError):
    pass


def require(ok):
    if not ok:
        raise Invalid()


def integer(v, lo=1, hi=U32):
    return type(v) is int and lo <= v <= hi


def typed(v, kind):
    if kind == "positive":
        return integer(v)
    if kind == "name":
        return type(v) is str and NAME.fullmatch(v) is not None
    if kind == "text":
        if type(v) is not str:
            return False
        try:
            v.encode("utf-8")
        except UnicodeEncodeError:
            return False
        return True
    if kind == "wire":
        return v is None or (type(v) is str and len(v) <= 96)
    if kind == "pair":
        return type(v) is list and len(v) == 2 and all(integer(x) for x in v)
    if kind == "unit":
        return (type(v) is list and len(v) == 3 and integer(v[0], 0)
                and integer(v[1]) and integer(v[2]))
    return False


def structural_validate(job):
    """Validate the job-local schema and static limits.

    Returns (event_count, policy_bytes, stage_count, policy_sizes) where
    policy_sizes is aligned with events (None outside stage events).  No
    policy grammar is evaluated here.
    """
    require(type(job) is dict and set(job) == JOB_KEYS)
    services = job["services"]
    limits = job["limits"]
    events = job["events"]

    require(type(services) is list and 1 <= len(services) <= 16)
    names = set()
    labels = set()
    for service in services:
        require(type(service) is dict and set(service) == {"name", "label"})
        name = service["name"]
        label = service["label"]
        require(typed(name, "name") and integer(label, 1, U32 - 1))
        require(name not in names and label not in labels)
        names.add(name)
        labels.add(label)

    require(type(limits) is dict and set(limits) == set(LIMITS))
    for key, value in limits.items():
        require(integer(value, 1, LIMITS[key]))

    require(type(events) is list and len(events) <= EVENT_COUNT_MAX)
    policy_sizes = [None] * len(events)
    policy_bytes = 0
    stage_count = 0
    for i, event in enumerate(events):
        require(type(event) is dict and type(event.get("op")) is str)
        op = event["op"]
        require(op in SCHEMA)
        fields = SCHEMA[op]
        require(set(event) == set(fields) | {"op"})
        for key, kind in fields.items():
            require(typed(event[key], kind))
        if op == "stage":
            # typed('text') guarantees the encode below succeeds.
            size = len(event["policy"].encode("utf-8"))
            policy_sizes[i] = size
            policy_bytes += size
            stage_count += 1
    return len(events), policy_bytes, stage_count, policy_sizes


def unique(pairs):
    d = {}
    for k, v in pairs:
        require(k not in d)
        d[k] = v
    return d


def invalid_constant(text):
    raise Invalid()


def integer_number(text):
    # The protocol's digit cap excludes a single leading minus and is a
    # whole-request JSON rule, so enforce it here as well as via CPython's
    # decoder limit.
    digits = text[1:] if text.startswith("-") else text
    require(len(digits) <= 4300)
    return int(text)


def float_number(text):
    value = float(text)
    require(math.isfinite(value))
    return value


def check_json_nesting(text):
    """Reject JSON container nesting beyond 64 before structural validation."""
    depth = 0
    quoted = False
    escaped = False
    for char in text:
        if quoted:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                quoted = False
            # Brackets/braces inside strings do not contribute.
        elif char == '"':
            quoted = True
        elif char == "[" or char == "{":
            depth += 1
            if depth > 64:
                raise Invalid()
        elif char == "]" or char == "}":
            depth -= 1
            if depth < 0:
                raise Invalid()
    require(depth == 0 and not quoted and not escaped)


def solve(data):
    try:
        require(len(data) <= RAW_MAX)
        try:
            text = data.decode("utf-8")
        except UnicodeDecodeError:
            raise Invalid()
        check_json_nesting(text)
        request = json.loads(
            text,
            object_pairs_hook=unique,
            parse_constant=invalid_constant,
            parse_float=float_number,
            parse_int=integer_number,
        )
        require(type(request) is dict and set(request) == {"jobs"})
        jobs = request["jobs"]
        require(type(jobs) is list and len(jobs) <= 4)
    except Exception:
        return {"error": "invalid"}

    # First establish which jobs are structurally valid.  Only these jobs
    # contribute to whole-request totals.
    validity = []
    metadata = []
    total_events = 0
    total_policy_bytes = 0
    total_stages = 0
    for job in jobs:
        try:
            meta = structural_validate(job)
        except Exception:
            validity.append(False)
            metadata.append(None)
            continue
        validity.append(True)
        metadata.append(meta)
        total_events += meta[0]
        total_policy_bytes += meta[1]
        total_stages += meta[2]

    if (total_events > EVENT_COUNT_MAX or total_policy_bytes > POLICY_BYTES_MAX
            or total_stages > STAGES_MAX):
        return {"error": "invalid"}

    # Parse every stage string in every structurally valid job for the
    # whole-request occurrence budget.  Grammar/bounds-invalid strings are
    # simply not counted; they will be rejected by their stage event.
    parsed_by_job = []
    total_atoms = 0
    total_paths = 0
    for job, valid, meta in zip(jobs, validity, metadata):
        cache = None
        if valid:
            events = job["events"]
            cache = [None] * len(events)
            for i, event in enumerate(events):
                if event["op"] != "stage":
                    continue
                try:
                    parsed = parse_policy(event["policy"])
                except Exception:
                    continue
                cache[i] = parsed
                total_atoms += parsed.atoms
                total_paths += parsed.path_symbols
                if total_atoms > ATOM_TOTAL_MAX or total_paths > PATH_TOTAL_MAX:
                    return {"error": "invalid"}
        parsed_by_job.append(cache)

    results = []
    for job, valid, cache in zip(jobs, validity, parsed_by_job):
        if not valid:
            results.append({"error": "invalid"})
            continue
        agent = Agent(job["services"], job["limits"])
        outcomes = []
        for i, event in enumerate(job["events"]):
            if event["op"] == "stage":
                outcomes.append(agent.event(event, parsed=cache[i]))
            else:
                outcomes.append(agent.event(event))
        results.append({"events": outcomes})
    return {"results": results}


def main():
    data = sys.stdin.buffer.read(RAW_MAX + 1)
    result = solve(data)
    output = json.dumps(result, separators=(",", ":"), ensure_ascii=True) + "\n"
    sys.stdout.write(output)


if __name__ == "__main__":
    main()

"""Policy syntax, AST and declared per-policy bounds.

This module intentionally evaluates no predicates.  It parses exactly the
language from the protocol and checks all syntax-local limits.  Registry
membership is checked later at staging time; occurrence counts for a
syntactically/bounds-valid string are still available when it names an
unregistered service.
"""
from __future__ import annotations

WS = " \t\f\r\n"
# The grammar's only ignored whitespace.  Vertical tab and every other
# Unicode whitespace character are deliberately not here.
ATOM_KINDS = ("match", "startswith", "endswith", "contains")
NONMATCH_KINDS = ("startswith", "endswith", "contains")

class PolicyError(ValueError):
    pass

class Pred:
    __slots__ = ("kind", "path", "left", "right", "child", "atoms", "depth",
                 "ps", "nmi")
    def __init__(self, kind, path=(), left=None, right=None, child=None,
                 atoms=1, depth=1):
        self.kind = kind
        self.path = path          # tuple of service names for atoms
        self.left = left
        self.right = right
        self.child = child
        self.atoms = atoms
        self.depth = depth
        # Filled by create_dfa after registry symbol binding.
        self.ps = None
        self.nmi = -1

class ParsedPolicy:
    __slots__ = ("rules", "atoms", "path_symbols", "match_paths",
                 "nonmatch_atoms", "referenced_names")
    def __init__(self, rules, atoms, path_symbols, match_paths,
                 nonmatch_atoms, referenced_names):
        # rules is [(Pred, "allow"|"drop"), ...]
        self.rules = rules
        self.atoms = atoms
        self.path_symbols = path_symbols
        self.match_paths = match_paths              # set of name tuples
        self.nonmatch_atoms = nonmatch_atoms        # insertion-ordered list
        self.referenced_names = referenced_names

_EMPTY = object()

class _Lexer:
    __slots__ = ("text", "n", "pos", "cur")
    def __init__(self, text):
        self.text = text
        self.n = len(text)
        self.pos = 0
        self.cur = _EMPTY

    def _scan(self):
        text = self.text
        n = self.n
        i = self.pos
        while i < n and text[i] in WS:
            i += 1
        if i >= n:
            self.pos = i
            return None
        c = text[i]
        if c in "(),;":
            self.pos = i + 1
            return (c, c)
        if ("A" <= c <= "Z") or ("a" <= c <= "z"):
            start = i
            i += 1
            while i < n:
                d = text[i]
                if ("A" <= d <= "Z") or ("a" <= d <= "z") or ("0" <= d <= "9"):
                    i += 1
                else:
                    break
            if i - start > 24:
                raise PolicyError("identifier bound")
            self.pos = i
            return ("WORD", text[start:i])
        # This includes VT, NBSP, unpaired surrogate code points, and all
        # punctuation not in the tiny policy grammar.
        raise PolicyError("syntax")

    def peek(self):
        if self.cur is _EMPTY:
            self.cur = self._scan()
        return self.cur

    def pop(self):
        tok = self.peek()
        self.cur = _EMPTY
        return tok

    def expect(self, kind, value=None):
        tok = self.pop()
        if tok is None or tok[0] != kind or (value is not None and tok[1] != value):
            raise PolicyError("syntax")
        return tok

    def accept(self, kind, value=None):
        tok = self.peek()
        if tok is not None and tok[0] == kind and (value is None or tok[1] == value):
            self.pop()
            return tok
        return None

class _Parser:
    __slots__ = ("lex", "atoms", "path_symbols", "match_paths",
                 "nonmatch_set", "nonmatch_atoms", "referenced")
    def __init__(self, text):
        self.lex = _Lexer(text)
        self.atoms = 0
        self.path_symbols = 0
        self.match_paths = set()
        self.nonmatch_set = set()
        self.nonmatch_atoms = []
        self.referenced = set()

    def _path(self):
        # Opening '(' has already been consumed.
        tok = self.lex.peek()
        path = []
        if tok is not None and tok[0] == ")":
            self.lex.pop()
            return tuple(path)
        tok = self.lex.expect("WORD")
        path.append(tok[1])
        while True:
            tok = self.lex.peek()
            if tok is not None and tok[0] == ",":
                self.lex.pop()
                path.append(self.lex.expect("WORD")[1])
            else:
                break
        self.lex.expect(")")
        if len(path) > 16:
            raise PolicyError("path bound")
        return tuple(path)

    def _atom(self, kind, path):
        self.atoms += 1
        if self.atoms > 32768:
            raise PolicyError("atom total")
        self.path_symbols += len(path)
        if self.path_symbols > 65536:
            raise PolicyError("path total")
        self.referenced.update(path)
        if kind == "match":
            self.match_paths.add(path)
        else:
            if len(path) > 4:
                raise PolicyError("non-match path bound")
            key = (kind, path)
            if key not in self.nonmatch_set:
                if len(self.nonmatch_set) >= 4:
                    raise PolicyError("non-match atom bound")
                self.nonmatch_set.add(key)
                self.nonmatch_atoms.append(key)
        return Pred(kind, path=path)

    def _predicate(self, level):
        # The deepest atom of a depth-16 predicate is visited at level 16.
        # This guard also protects Python's call stack on malformed input.
        if level > 16:
            raise PolicyError("depth")
        tok = self.lex.peek()
        if tok is None:
            raise PolicyError("syntax")
        if tok[0] == "(":
            self.lex.pop()
            left = self._predicate(level + 1)
            optok = self.lex.peek()
            if optok is None or optok[0] != "WORD" or optok[1] not in ("and", "or"):
                raise PolicyError("syntax")
            op = self.lex.pop()[1]
            right = self._predicate(level + 1)
            self.lex.expect(")")
            depth = 1 + (left.depth if left.depth >= right.depth else right.depth)
            if depth > 16:
                raise PolicyError("depth")
            return Pred(op, left=left, right=right,
                        atoms=left.atoms + right.atoms, depth=depth)
        if tok[0] != "WORD":
            raise PolicyError("syntax")
        word = tok[1]
        if word in ATOM_KINDS:
            self.lex.pop()
            self.lex.expect("(")
            path = self._path()
            return self._atom(word, path)
        if word == "not":
            self.lex.pop()
            self.lex.expect("(")
            child = self._predicate(level + 1)
            self.lex.expect(")")
            depth = child.depth + 1
            if depth > 16:
                raise PolicyError("depth")
            return Pred("not", child=child, atoms=child.atoms, depth=depth)
        raise PolicyError("syntax")

    def parse(self):
        rules = []
        complex_count = 0
        while True:
            if self.lex.peek() is None:
                break
            pred = self._predicate(1)
            act = self.lex.expect("WORD")
            if act[1] not in ("allow", "drop"):
                raise PolicyError("syntax")
            self.lex.expect(";")
            if pred.kind != "match":
                complex_count += 1
                if complex_count > 8:
                    raise PolicyError("complex rule bound")
                if pred.atoms > 32:
                    raise PolicyError("expression atom bound")
            rules.append((pred, act[1]))
        # The AST uses Pred("atom", ...) internally; user-facing AST views
        # are not important, but keeping this one-kind representation makes
        # the evaluator compact.
        return ParsedPolicy(rules, self.atoms, self.path_symbols,
                            self.match_paths, tuple(self.nonmatch_atoms),
                            frozenset(self.referenced))

def parse_policy(text):
    """Parse and bounds-check one policy string.

    Raises PolicyError for grammar or per-string bound failures.  Registry
    membership is deliberately not considered here.
    """
    if type(text) is not str:
        raise PolicyError("type")
    return _Parser(text).parse()

def parse(text, names=None):
    """Compatibility helper: return (parsed_policy, atoms, path_symbols).

    If *names* is supplied, paths containing names outside it raise, as the
    starter syntax module did.  The driver uses :func:`parse_policy` so that
    occurrence totals can be counted before registry checking.
    """
    p = parse_policy(text)
    if names is not None:
        for n in p.referenced_names:
            if n not in names:
                raise PolicyError("unregistered")
    return p, p.atoms, p.path_symbols

"""In-memory CPU control-plane agent implementing the protocol lifecycle."""
from __future__ import annotations

import re
import struct

from .create_dfa import DENY, create
from syntax import PolicyError, parse_policy

_U32 = 4294967295
_HEX48 = re.compile(r"[0-9A-Fa-f]{48}\Z")
_MISSING = object()

class Rejected(Exception):
    pass

class ImageRec:
    __slots__ = ("accept", "rows", "cell_count", "refs")
    def __init__(self, image, cell_count):
        self.accept = image["accept"]
        self.rows = image["rows"]
        self.cell_count = cell_count
        self.refs = 0

class Context:
    __slots__ = ("epoch", "state")
    def __init__(self, epoch, state):
        self.epoch = epoch
        self.state = state

class Unit:
    __slots__ = ("ns", "pid", "gen", "service", "mark", "contexts")
    def __init__(self, ns, pid, gen, service, mark=0, contexts=None):
        self.ns = ns
        self.pid = pid
        self.gen = gen
        self.service = service
        self.mark = mark
        self.contexts = {} if contexts is None else contexts
    @property
    def triple(self):
        return (self.ns, self.pid, self.gen)

class Packet:
    __slots__ = ("epoch", "state", "destination", "wire", "receipt")
    def __init__(self, epoch, state, destination, wire):
        self.epoch = epoch
        self.state = state
        self.destination = destination
        self.wire = wire
        self.receipt = None          # (unit_triple, rid, epoch, state)

class Connection:
    __slots__ = ("gen", "mark", "packets")
    def __init__(self, gen):
        self.gen = gen
        self.mark = 0
        self.packets = {}

class FileRec:
    __slots__ = ("gen", "epoch", "state")
    def __init__(self, gen, epoch, state):
        self.gen = gen
        self.epoch = epoch
        self.state = state

class MemoryMap:
    """Compatibility no-op view of the historical CPU transition map."""
    def __init__(self):
        self.entries = {}
    def __setitem__(self, key, value):
        self.entries[key] = value

class Agent:
    def __init__(self, services, limits):
        self.services = services
        self.limits = limits
        ordered = sorted(services, key=lambda s: s["label"])
        self.sym_of = {s["name"]: i for i, s in enumerate(ordered)}
        self.label_of = {s["name"]: s["label"] for s in services}
        self.m = len(ordered)

        self.images = {}
        self.active = None
        self.stage_hw = 0
        self.cells_used = 0

        self.units = {}              # (namespace,pid) -> Unit
        self.unit_hw = {}            # (namespace,pid) -> generation high-water
        self.context_count = 0

        self.connections = {}        # connection id -> Connection
        self.conn_hw = {}            # connection id -> generation high-water
        self.packet_count = 0

        self.files = {}              # file id -> FileRec
        self.file_hw = {}            # file id -> generation high-water

    # ---- small helpers -------------------------------------------------
    def _live_unit(self, u):
        rec = self.units.get((u[0], u[1]))
        if rec is None or rec.gen != u[2]:
            raise Rejected()
        return rec

    def _open_conn(self, c):
        rec = self.connections.get(c[0])
        if rec is None or rec.gen != c[1]:
            raise Rejected()
        return rec

    def _current_file(self, f):
        rec = self.files.get(f[0])
        if rec is None or rec.gen != f[1]:
            raise Rejected()
        return rec

    def _advance(self, rec, state, service):
        if state == DENY:
            return DENY
        return rec.rows[state][self.sym_of[service]]

    def _wire(self, epoch, state, destination_label, stream, connection_gen):
        return struct.pack(">4sIIIII", b"EMC4", epoch, state,
                           destination_label, stream, connection_gen).hex()

    @staticmethod
    def _wire_ok(candidate, expected):
        if type(candidate) is not str or len(candidate) != 48:
            return False
        if _HEX48.fullmatch(candidate) is None:
            return False
        return candidate.lower() == expected

    def _inc_ref(self, epoch):
        rec = self.images.get(epoch)
        if rec is None:
            raise Rejected()
        rec.refs += 1

    def _dec_ref(self, epoch):
        rec = self.images.get(epoch)
        if rec is None or rec.refs <= 0:
            raise Rejected()
        rec.refs -= 1

    # ---- replay --------------------------------------------------------
    def event(self, event, parsed=_MISSING):
        try:
            return self._event(event, parsed)
        except (Rejected, PolicyError, KeyError, IndexError, ValueError,
                struct.error):
            return {"error": "rejected"}

    def _event(self, e, parsed):
        op = e["op"]
        if op == "stage":
            return self._stage(e, parsed)
        if op == "commit":
            ep = e["epoch"]
            if ep not in self.images:
                raise Rejected()
            self.active = ep
            return {"ok": True}
        if op == "retire":
            ep = e["epoch"]
            rec = self.images.get(ep)
            if rec is None or self.active == ep or rec.refs != 0:
                raise Rejected()
            del self.images[ep]
            self.cells_used -= rec.cell_count
            return {"ok": True}
        if op == "spawn":
            return self._spawn(e)
        if op == "clone":
            return self._clone(e)
        if op == "exit":
            return self._exit(e)
        if op == "begin":
            return self._begin(e)
        if op == "finish":
            return self._finish(e)
        if op == "open":
            return self._open(e)
        if op == "send":
            return self._send(e)
        if op == "recv":
            return self._recv(e)
        if op == "close":
            return self._close(e)
        if op == "store":
            return self._store(e)
        if op == "load":
            return self._load(e)
        if op == "unlink":
            return self._unlink(e)
        if op == "inspect":
            return self._inspect()
        raise Rejected()

    def _stage(self, e, parsed):
        ep = e["epoch"]
        if ep <= self.stage_hw:
            raise Rejected()
        if len(self.images) >= self.limits["images"]:
            raise Rejected()
        if parsed is _MISSING:
            try:
                parsed = parse_policy(e["policy"])
            except PolicyError:
                raise Rejected()
        elif parsed is None:
            raise Rejected()
        image = create(e["policy"], self.services, parsed=parsed)
        cell_count = 0
        for row in image["rows"]:
            for target in row:
                if target != DENY:
                    cell_count += 1
        if self.cells_used + cell_count > self.limits["cells"]:
            raise Rejected()
        # Publication is a single dictionary insertion after every check.
        rec = ImageRec(image, cell_count)
        self.images[ep] = rec
        self.stage_hw = ep
        self.cells_used += cell_count
        return {"ok": True, "epoch": ep, "image": image}

    def _spawn(self, e):
        u = e["unit"]
        pair = (u[0], u[1])
        if pair in self.units or u[2] <= self.unit_hw.get(pair, 0):
            raise Rejected()
        service = e["service"]
        if service not in self.sym_of:
            raise Rejected()
        if len(self.units) >= self.limits["units"]:
            raise Rejected()
        unit = Unit(u[0], u[1], u[2], service)
        self.units[pair] = unit
        self.unit_hw[pair] = u[2]
        return {"ok": True}

    def _clone(self, e):
        parent = self._live_unit(e["parent"])
        c = e["child"]
        cpair = (c[0], c[1])
        if cpair in self.units or c[2] <= self.unit_hw.get(cpair, 0):
            raise Rejected()
        nctx = len(parent.contexts)
        if len(self.units) >= self.limits["units"]:
            raise Rejected()
        if self.context_count + nctx > self.limits["contexts"]:
            raise Rejected()
        copies = {rid: Context(ctx.epoch, ctx.state)
                  for rid, ctx in parent.contexts.items()}
        child = Unit(c[0], c[1], c[2], parent.service,
                     mark=parent.mark, contexts=copies)
        # Commit unit and all copies.  The image references are independent
        # per copied context.
        self.units[cpair] = child
        self.unit_hw[cpair] = c[2]
        self.context_count += nctx
        for ctx in copies.values():
            self._inc_ref(ctx.epoch)
        return {"ok": True}

    def _exit(self, e):
        u = self._live_unit(e["unit"])
        pair = (u.ns, u.pid)
        for ctx in u.contexts.values():
            self._dec_ref(ctx.epoch)
        self.context_count -= len(u.contexts)
        del self.units[pair]
        return {"ok": True}

    def _begin(self, e):
        u = self._live_unit(e["unit"])
        rid = e["rid"]
        if self.active is None:
            raise Rejected()
        rec = self.images.get(self.active)
        if rec is None or rid <= u.mark:
            raise Rejected()
        if self.context_count >= self.limits["contexts"]:
            raise Rejected()
        state = self._advance(rec, 0, u.service)
        u.contexts[rid] = Context(self.active, state)
        u.mark = rid
        self.context_count += 1
        rec.refs += 1
        return {"ok": True, "epoch": self.active, "state": state}

    def _finish(self, e):
        u = self._live_unit(e["unit"])
        rid = e["rid"]
        ctx = u.contexts.pop(rid, None)
        if ctx is None:
            raise Rejected()
        self.context_count -= 1
        self._dec_ref(ctx.epoch)
        rec = self.images[ctx.epoch]
        allow = ctx.state != DENY and bool(rec.accept[ctx.state])
        return {"ok": True, "allow": allow}

    def _open(self, e):
        c = e["connection"]
        cid, gen = c[0], c[1]
        if cid in self.connections or gen <= self.conn_hw.get(cid, 0):
            raise Rejected()
        if len(self.connections) >= self.limits["connections"]:
            raise Rejected()
        self.connections[cid] = Connection(gen)
        self.conn_hw[cid] = gen
        return {"ok": True}

    def _send(self, e):
        u = self._live_unit(e["unit"])
        ctx = u.contexts.get(e["rid"])
        if ctx is None:
            raise Rejected()
        conn = self._open_conn(e["connection"])
        stream = e["stream"]
        if stream <= conn.mark:
            raise Rejected()
        destination = e["destination"]
        label = self.label_of.get(destination)
        if label is None:
            raise Rejected()
        if self.packet_count >= self.limits["packets"]:
            raise Rejected()
        wire = self._wire(ctx.epoch, ctx.state, label, stream, conn.gen)
        rec = self.images.get(ctx.epoch)
        if rec is None:
            raise Rejected()
        conn.packets[stream] = Packet(ctx.epoch, ctx.state, destination, wire)
        conn.mark = stream
        self.packet_count += 1
        rec.refs += 1
        return {"ok": True, "wire": wire}

    def _recv(self, e):
        conn = self._open_conn(e["connection"])
        stream = e["stream"]
        packet = conn.packets.get(stream)
        if packet is None:
            raise Rejected()
        u = self._live_unit(e["unit"])
        if u.service != packet.destination:
            raise Rejected()
        wire = e["wire"]
        if wire is not None and not self._wire_ok(wire, packet.wire):
            raise Rejected()
        rid = e["rid"]
        receipt = packet.receipt
        if receipt is not None:
            r_triple, r_rid, r_epoch, r_state = receipt
            if u.triple != r_triple or rid != r_rid:
                raise Rejected()
            ctx = u.contexts.get(rid)
            if ctx is None or ctx.epoch != r_epoch or ctx.state != r_state:
                raise Rejected()
            return {"ok": True, "epoch": r_epoch, "state": r_state}
        if rid <= u.mark:
            raise Rejected()
        if self.context_count >= self.limits["contexts"]:
            raise Rejected()
        rec = self.images.get(packet.epoch)
        if rec is None:
            raise Rejected()
        state = self._advance(rec, packet.state, u.service)
        ctx = Context(packet.epoch, state)
        u.contexts[rid] = ctx
        u.mark = rid
        self.context_count += 1
        rec.refs += 1
        receipt = (u.triple, rid, packet.epoch, state)
        packet.receipt = receipt
        return {"ok": True, "epoch": packet.epoch, "state": state}

    def _close(self, e):
        conn = self._open_conn(e["connection"])
        cid = e["connection"][0]
        for packet in conn.packets.values():
            self._dec_ref(packet.epoch)
        self.packet_count -= len(conn.packets)
        del self.connections[cid]
        return {"ok": True}

    def _store(self, e):
        u = self._live_unit(e["unit"])
        ctx = u.contexts.get(e["rid"])
        if ctx is None:
            raise Rejected()
        fid, gen = e["file"][0], e["file"][1]
        cur = self.files.get(fid)
        if cur is None:
            if gen <= self.file_hw.get(fid, 0):
                raise Rejected()
            if len(self.files) >= self.limits["files"]:
                raise Rejected()
            self._inc_ref(ctx.epoch)
            self.files[fid] = FileRec(gen, ctx.epoch, ctx.state)
            self.file_hw[fid] = gen
            return {"ok": True}
        if gen != cur.gen:
            raise Rejected()
        old_epoch = cur.epoch
        # Atomic overwrite: adjust the one file reference in place.
        if old_epoch != ctx.epoch:
            self._dec_ref(old_epoch)
            self._inc_ref(ctx.epoch)
        cur.epoch = ctx.epoch
        cur.state = ctx.state
        return {"ok": True}

    def _load(self, e):
        cur = self._current_file(e["file"])
        u = self._live_unit(e["unit"])
        rid = e["rid"]
        if rid <= u.mark:
            raise Rejected()
        if self.context_count >= self.limits["contexts"]:
            raise Rejected()
        rec = self.images.get(cur.epoch)
        if rec is None:
            raise Rejected()
        state = self._advance(rec, cur.state, u.service)
        u.contexts[rid] = Context(cur.epoch, state)
        u.mark = rid
        self.context_count += 1
        rec.refs += 1
        return {"ok": True, "epoch": cur.epoch, "state": state}

    def _unlink(self, e):
        f = e["file"]
        cur = self._current_file(f)
        self._dec_ref(cur.epoch)
        del self.files[f[0]]
        return {"ok": True}

    def _inspect(self):
        entries = []
        for ep in sorted(self.images):
            rec = self.images[ep]
            entries.append([ep, len(rec.rows), rec.cell_count, rec.refs])
        return {
            "ok": True,
            "active": self.active,
            "images": entries,
            "units": len(self.units),
            "contexts": self.context_count,
            "connections": len(self.connections),
            "packets": self.packet_count,
            "files": len(self.files),
        }

