from ebpf.helper import _priority
import random
def depth_from_sorted(keys):
 # simulate treap shape by priority Cartesian tree: depth can compute recursion from min priority root
 # just build insert nodes via helper?
 from ebpf.helper import _treap_insert
 t=None
 for k in keys:t=_treap_insert(t,k,None)
