cd /workspace && python3 - <<'PY'
import json,sys,time
sys.path.insert(0,'/workspace/project');import driver
lim={'images':1,'cells':1,'units':1,'contexts':1,'connections':1,'packets':1,'files':1}
for n in [2097152,2097153]:
 pol='😀'*n
 job={'services':[{'name':'A','label':1}],'limits':lim,'events':[{'op':'stage','epoch':1,'policy':pol}]}
 data=json.dumps({'jobs':[job]},separators=(',',':')).encode();print('chars',n,'bytes',len(data))
 t=time.time();r=driver.solve(data);print(r,'time',time.time()-t)
PY

cd /workspace && python3 - <<'PY'
import json,sys,time
sys.path.insert(0,'/workspace/project');import driver
lim={'images':1,'cells':1,'units':1,'contexts':1,'connections':1,'packets':1,'files':1}
for n in [2097152,2097153]:
 pol='😀'*n
 job={'services':[{'name':'A','label':1}],'limits':lim,'events':[{'op':'stage','epoch':1,'policy':pol}]}
 data=json.dumps({'jobs':[job]},separators=(',',':'),ensure_ascii=False).encode('utf-8');print('chars',n,'bytes',len(data))
 t=time.time();r=driver.solve(data);print(r,'time',time.time()-t)
PY
